package com.iortatechnxt.brokerverse.journal.service;

import com.iortatechnxt.brokerverse.journal.api.dto.JournalLineRequest;
import com.iortatechnxt.brokerverse.journal.domain.JournalType;
import java.time.LocalDate;
import java.util.List;

/**
 * Journal generated by the accounting engine or a period-end process.
 *
 * <p>{@code sourceModule} + {@code sourceReference} form an idempotency key: submitting the same
 * key twice returns the already posted journal instead of double posting.
 *
 * @param companyId company
 * @param branchId branch
 * @param journalType system journal type
 * @param valueDate accounting date
 * @param currency header currency
 * @param narration narration
 * @param reference business reference (policy, claim, receipt no...)
 * @param sourceModule originating module, e.g. "UNDERWRITING"
 * @param sourceReference unique key of the business event
 * @param lines lines
 */
public record SystemJournalRequest(
    Long companyId,
    Long branchId,
    JournalType journalType,
    LocalDate valueDate,
    String currency,
    String narration,
    String reference,
    String sourceModule,
    String sourceReference,
    List<JournalLineRequest> lines) {}
